import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] x = new int[6];
        int sum = 0;
        for (int i = 0; i < 6; i++) {
            x[i] = sc.nextInt();
            sum += x[i];
        }

        // A soma total deve ser divisivel por 3
        if (sum % 3 != 0) {
            System.out.println('N');
            return;
        }

        int t = sum / 3;

        // O topo deve ser um unico cubo de peso t;
        //Entre os restantes, dois cubos devem somar t;
        //Os tres restantes entao somam automaticamente t.
        for (int i = 0; i < 6; i++) {
            if (x[i] != t) continue;
            for (int j = 0; j < 6; j++) {
                if (j == i) continue;
                for (int k = j + 1; k < 6; k++) {
                    if (k == i) continue;
                    if (x[j] + x[k] == t) {
                        System.out.println('S');
                        return;
                    }
                }
            }
        }

        System.out.println('N');
    }
}
